package com.sunrise.dentalclinic.controller;
import com.sunrise.dentalclinic.dto.TreatmentRequest;import com.sunrise.dentalclinic.service.TreatmentService;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/treatments") public class TreatmentController{private final TreatmentService service;public TreatmentController(TreatmentService s){service=s;}@GetMapping String list(Model m){m.addAttribute("treatments",service.all());return "treatments/list";}@GetMapping("/new")String create(Model m){m.addAttribute("treatmentRequest",new TreatmentRequest("",null));return "treatments/form";}@PostMapping String save(@Valid @ModelAttribute TreatmentRequest treatmentRequest,BindingResult e){if(e.hasErrors())return "treatments/form";service.create(treatmentRequest);return "redirect:/treatments";}@GetMapping("/{id}/edit")String edit(@PathVariable Long id,Model m){var t=service.get(id);m.addAttribute("treatment",t);m.addAttribute("treatmentRequest",new TreatmentRequest(t.getTreatmentName(),t.getTreatmentCost()));return "treatments/form";}@PostMapping("/{id}")String update(@PathVariable Long id,@Valid @ModelAttribute TreatmentRequest treatmentRequest,BindingResult e,Model m){if(e.hasErrors()){m.addAttribute("treatment",service.get(id));return "treatments/form";}service.update(id,treatmentRequest);return "redirect:/treatments";}@PostMapping("/{id}/toggle")String toggle(@PathVariable Long id){service.toggle(id);return "redirect:/treatments";}}
